538	fn current_appearance(browser_window: &web_sys::Window) -> WindowAppearance {
539	    let is_dark = browser_window
540	        .match_media("(prefers-color-scheme: dark)")
541	        .ok()
542	        .flatten()
543	        .map(|mql| mql.matches())
544	        .unwrap_or(false);
545	
546	    if is_dark {
547	        WindowAppearance::Dark
548	    } else {
549	        WindowAppearance::Light
550	    }
551	}
