566	// Safari does not support `devicePixelContentBoxSize`, so detect whether it's available.
567	fn check_device_pixel_support() -> bool {
568	    let global: JsValue = js_sys::global().into();
569	    let Ok(constructor) = js_sys::Reflect::get(&global, &"ResizeObserverEntry".into()) else {
570	        return false;
571	    };
572	    let Ok(prototype) = js_sys::Reflect::get(&constructor, &"prototype".into()) else {
573	        return false;
574	    };
575	    let descriptor = js_sys::Object::get_own_property_descriptor(
576	        &prototype.unchecked_into::<js_sys::Object>(),
577	        &"devicePixelContentBoxSize".into(),
578	    );
