8	// Prime counting (intentionally brute-force so it hammers the CPU)
9	// ---------------------------------------------------------------------------
10	
11	fn is_prime(n: u64) -> bool {
12	    if n < 2 {
13	        return false;
14	    }
15	    if n < 4 {
16	        return true;
17	    }
18	    if n % 2 == 0 || n % 3 == 0 {
19	        return false;
20	    }
21	    let mut i = 5;
22	    while i * i <= n {
23	        if n % i == 0 || n % (i + 2) == 0 {
24	            return false;
25	        }
26	        i += 6;
27	    }
28	    true
29	}
30	
31	fn count_primes_in_range(start: u64, end: u64) -> u64 {
32	    let mut count = 0;
33	    for n in start..end {
34	        if is_prime(n) {
35	            count += 1;
36	        }
37	    }
38	    count
39	}
