107	    fn start_search(&mut self, cx: &mut Context<Self>) {
108	        let limit = self.selected_preset.value();
109	        let chunk_size = limit / NUM_CHUNKS;
110	
111	        self.current_run = Some(Run {
112	            limit,
113	            chunks_done: 0,
